use crate::{policy::Operation, recovery::model::{RecoveryEnvelopeV1, ValidationError}};
pub fn operation_json(operation: &Operation) -> String { match operation { Operation::LauncherPolicy { allowed } => format!(r#"{{"allowed_packages":[{}],"kind":"launcher_policy"}}"#, allowed.iter().map(|p| format!("\"{}\"", p.as_str())).collect::<Vec<_>>().join(",")), Operation::Suspend { package, user, suspended } => format!(r#"{{"kind":"package_suspension","package_id":"{}","suspended":{},"user_id":{}}}"#, package.as_str(), suspended, user.get()), Operation::AppOp { package, user, app_op, mode } => format!(r#"{{"kind":"app_op","mode":"{}","op":"{}","package_id":"{}","user_id":{}}}"#, match mode { crate::adb::AppOpMode::Default => "default", crate::adb::AppOpMode::Allow => "allow", crate::adb::AppOpMode::Ignore => "ignore" }, app_op.as_str(), package.as_str(), user.get()), Operation::Home { component } => format!(r#"{{"component":"{}","kind":"home"}}"#, component.as_str()), Operation::Maintenance { open } => format!(r#"{{"kind":"maintenance","open":{open}}}"#), Operation::Verify => r#"{"kind":"maintenance","open":false}"#.into() } }
pub fn pending(envelope: &RecoveryEnvelopeV1, index: usize, operation: &Operation, inverse: &Operation) -> Result<(String, RecoveryEnvelopeV1), ValidationError> { let id = format!("00000000-0000-4000-8000-{index:012x}"); Ok((id.clone(), envelope.append_pending(&id, &operation_json(operation), &operation_json(inverse))?)) }
